def handle(app, svc):
    resp = svc.apply(app)
    decision = resp.get("decision")
    limit = resp.get("limit", 0)

    # Network referral rule: self_employed with requested_limit above 7000
    # must go to manual review instead of being issued. A decline stays a decline.
    if (app.get("employment") == "self_employed"
            and app.get("requested_limit", 0) > 7000
            and decision == "approve"):
        return {"action": "queue_review", "limit": 0}

    if decision == "approve":
        return {"action": "issue", "limit": limit}
    if decision == "refer":
        return {"action": "queue_review", "limit": 0}
    # decline
    return {"action": "decline", "limit": 0}
